inseridos as (
  insert into chamados (id_solicitacao, id_pedido, numero_filial, canal_venda, modal_logistico, valor_pedido, solicitante, tipo_ocorrencia, status, perda, ordem, cadastrado_por, responsavel_proxima_acao, descricao, data_criacao)
  select
    d.id_solicitacao, d.id_pedido,
    (select f.numero_filial from filiais f where f.numero_filial = d.numero_filial),
    d.canal_venda, d.modal_logistico, d.valor_pedido, d.solicitante, d.tipo_ocorrencia,
    d.status, d.perda, d.ordem, d.cadastrado_por, d.responsavel_proxima_acao, d.descricao,
    d.data_criacao::timestamptz
  from dados d
  on conflict (id_solicitacao) do update set
    id_pedido = excluded.id_pedido,
    numero_filial = excluded.numero_filial,
    canal_venda = excluded.canal_venda,
    modal_logistico = excluded.modal_logistico,
    valor_pedido = excluded.valor_pedido,
    solicitante = excluded.solicitante,
    tipo_ocorrencia = excluded.tipo_ocorrencia,
    status = excluded.status,
    perda = excluded.perda,
    ordem = excluded.ordem,
    cadastrado_por = excluded.cadastrado_por,
    responsavel_proxima_acao = excluded.responsavel_proxima_acao,
    descricao = excluded.descricao,
    data_criacao = excluded.data_criacao
  where chamados.numero_filial is null
  returning id, data_criacao
)
insert into historico_chamados (chamado_id, usuario, descricao, data_hora)
select id, 'Importação (histórico)', 'Chamado importado da planilha de acompanhamento (dados históricos).', data_criacao
from inseridos;
